insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$balsa-nova$q$, $q$https://www.diariomunicipal.com.br/amp/materia/6C883C1E (Lei 1.411/2024, Diário Oficial dos Municípios do Paraná)$q$, $q$Ato oficial de Balsa Nova: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM). Trecho montado pela malha de ruas (Valhalla/OSM) entre as coordenadas UTM do ato.$q$, 6, $q$Lei 1.411/2024: caminhões com 4 eixos ou mais (cavalo + carreta em conjunto), carregados ou não, na Estrada Municipal Atílio Ramos; coordenadas UTM do ato convertidas de SIRGAS 2000 / UTM 22S (EPSG:31982; o datum do ato não é dito). Sinalização (art. 4º) não confirmada. Divergência do OSM registrada sem correção: Av. Fritz Erwin Schmidt com maxweight=50 (way 383957149), sem ato municipal. Balsa Nova não define VUC nos atos lidos.$q$);
